// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

interface IDataFeed { function latestValue() external view returns (int256 value, uint256 updatedAt); }
contract OracleConsumer {
    function isFresh(uint256 updatedAt) external view returns (bool) { return updatedAt <= block.timestamp && block.timestamp - updatedAt < 1 hours; }
}
